[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=0.46]
\usetikzlibrary{angles,quotes}
\coordinate (A) at (0,0);
\coordinate (B) at (2.536,5.438);
\coordinate (C) at (10.93,0);
\draw (A)--(B) node[midway,above left] {$6$};
\draw (B)--(C) node[midway,above right] {$10$};
\draw (A)--(C);
\pic[draw,"$65^{\circ}$",angle radius=1cm,angle eccentricity=1.4] {angle=C--A--B};
\pic[draw,"$\theta$",angle radius=1cm,angle eccentricity=1.5] {angle=B--C--A};
\end{tikzpicture}
[/tikz]
Find the angle $\theta$, correct to $2$ decimal places.

[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=0.6]
\usetikzlibrary{angles,quotes}
\coordinate (A) at (6,0);
\coordinate (B) at (0,0);
\coordinate (C) at (-2.77,4.8);
\draw (A)--(B) node[midway,below] {$6$};
\draw (A)--(C) node[midway,above right] {$10$};
\draw (B)--(C);
\pic[draw,"$120^{\circ}$",angle radius=0.9cm,angle eccentricity=1.35] {angle=A--B--C};
\pic[draw,"$\theta$",angle radius=0.9cm,angle eccentricity=1.6] {angle=B--C--A};
\end{tikzpicture}
[/tikz]
The angle marked $120^{\circ}$ is opposite the side of length $10$. Find the angle $\theta$, correct to $2$ decimal places.

